package com.dennis.aimasteringlab;
import java.util.concurrent.FutureTask;import java.util.concurrent.atomic.AtomicInteger;
public final class BackgroundJobHarness{public static void main(String[]a){AtomicInteger n=new AtomicInteger();MasteringJobControl.Listener l=s->n.incrementAndGet();MasteringJobControl.attach(l);FutureTask<Void>f=new FutureTask<>(()->null);MasteringJobControl.register(f);MasteringJobControl.update("Measured background progress",47);MasteringJobControl.Snapshot s=MasteringJobControl.snapshot();req(s.running&&!s.finished&&s.percent==47,"progress");MasteringJobControl.complete(true,"Master saved and verified");s=MasteringJobControl.snapshot();req(!s.running&&s.finished&&s.success&&s.percent==100,"completion");MasteringJobControl.clear(f);FutureTask<Void>c=new FutureTask<>(()->null);MasteringJobControl.register(c);req(MasteringJobControl.cancel()&&c.isCancelled(),"cancel");MasteringJobControl.complete(false,"Cancelled safely");MasteringJobControl.clear(c);MasteringJobControl.detach(l);req(n.get()>=6,"callbacks");System.out.println("BACKGROUND_JOB_PASS callbacks="+n.get());}private static void req(boolean c,String m){if(!c)throw new AssertionError(m);}}
